import { useEffect, useMemo, useState } from "react";
import {
  ArrowUpRight,
  BarChart3,
  ClipboardCheck,
  BookOpen,
  Check,
  ChevronRight,
  Clock3,
  FileCheck2,
  FileText,
  Filter,
  FolderOpen,
  GraduationCap,
  LayoutDashboard,
  LockKeyhole,
  MoreHorizontal,
  Plus,
  Search,
  Settings2,
  ShieldCheck,
  Sparkles,
  Target,
  UploadCloud,
  Users,
  X,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import Guide, { GuideEmptyState } from "@/pages/Guide";

const navItems = [
  { label: "概要", icon: LayoutDashboard },
  { label: "資料ライブラリ", icon: FolderOpen },
  { label: "問題バンク", icon: FileCheck2 },
  { label: "テスト管理", icon: GraduationCap },
  { label: "結果分析", icon: BarChart3 },
  { label: "記述採点", icon: ClipboardCheck },
  { label: "使用説明書", icon: BookOpen },
];

type MaterialCard = { title: string; type: string; category: string; pages: number; keywords: string[]; text: string; headings: string[]; figureDescriptions: string[]; status: string; updated: string; color: string };
const materials: MaterialCard[] = [];

const questionTypes = ["四択", "複数選択", "正誤", "優先順位", "数値読解", "資料比較", "短文記述"];

export default function Home() {
  const [activeNav, setActiveNav] = useState("概要");
  const [showGenerator, setShowGenerator] = useState(false);
  const [showUpload, setShowUpload] = useState(false);
  const [generated, setGenerated] = useState(false);
  const [materialSearch, setMaterialSearch] = useState("");
  const [toast, setToast] = useState("");
  const [candidateMode, setCandidateMode] = useState(false);
  const [selectedMaterial, setSelectedMaterial] = useState<MaterialCard | null>(null);
  const utils = trpc.useUtils();
  const { data: materialRows = [] } = trpc.materials.list.useQuery();
  const materialItems = useMemo<MaterialCard[]>(() => materialRows.map((row) => ({ title: row.title, type: row.fileType.toUpperCase(), category: row.category, pages: row.pageCount, keywords: Array.isArray(row.keywords) ? row.keywords as string[] : [], text: row.extractedText ?? "", headings: Array.isArray(row.headings) ? row.headings as string[] : [], figureDescriptions: Array.isArray(row.figureDescriptions) ? row.figureDescriptions as string[] : [], status: row.usageStatus === "active" ? "利用中" : "利用停止", updated: new Date(row.updatedAt).toLocaleDateString(), color: "sky" })), [materialRows]);

  const filteredMaterials = useMemo(
    () => materialItems.filter((item) => item.title.toLowerCase().includes(materialSearch.toLowerCase()) || item.category.includes(materialSearch)),
    [materialItems, materialSearch],
  );

  const notify = (message: string) => {
    setToast(message);
    window.setTimeout(() => setToast(""), 2600);
  };

  return (
    <div className="min-h-screen bg-[#f5f7fb] text-[#172033]">
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-[248px] border-r border-slate-200 bg-white lg:flex lg:flex-col">
        <div className="flex h-[76px] items-center gap-3 border-b border-slate-100 px-7">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#132b4f] text-white shadow-lg shadow-blue-950/15"><ShieldCheck className="h-5 w-5" /></div>
          <div><p className="text-[15px] font-bold tracking-tight">SourceBound</p><p className="text-[11px] font-medium text-slate-400">EXAM PLATFORM</p></div>
        </div>
        <div className="px-4 pt-7"><p className="px-3 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Workspace</p></div>
        <nav className="space-y-1 px-4 pt-3">
          {navItems.map((item) => {
            const Icon = item.icon;
            const active = activeNav === item.label;
            return <button key={item.label} onClick={() => setActiveNav(item.label)} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${active ? "bg-[#eaf1f9] text-[#16365f]" : "text-slate-500 hover:bg-slate-50 hover:text-slate-900"}`}><Icon className={`h-[18px] w-[18px] ${active ? "text-[#1e5a94]" : "text-slate-400 group-hover:text-slate-600"}`} />{item.label}{item.label === "問題バンク" && <span className="ml-auto rounded-full bg-[#dcecff] px-2 py-0.5 text-[10px] text-[#216096]">0</span>}</button>;
          })}
        </nav>
        <div className="mt-auto p-4"><div className="rounded-2xl bg-[#f1f6fb] p-4"><div className="mb-3 flex items-center gap-2 text-xs font-bold text-[#23476f]"><Sparkles className="h-4 w-4 text-[#df8a42]" />AI品質ガード</div><p className="text-xs leading-5 text-slate-500">問題の70%以上が複数根拠・資料内条件を参照しています。</p><div className="mt-3 flex items-center justify-between text-[11px] font-bold"><span className="text-slate-500">現在の達成率</span><span className="text-[#1d5d8f]">78%</span></div><Progress value={78} className="mt-2 h-1.5 bg-white [&>div]:bg-[#1d5d8f]" /></div><button className="mt-4 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-500 hover:bg-slate-50"><Settings2 className="h-4 w-4" />ワークスペース設定</button></div>
      </aside>

      <main className="lg:pl-[248px]">
        <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-slate-200 bg-white/90 px-5 backdrop-blur md:px-9">
          <div><p className="text-xs font-semibold text-slate-400">管理者コンソール / {activeNav}</p><h1 className="mt-1 text-xl font-bold tracking-tight text-[#162b49]">{activeNav}</h1></div>
          <div className="flex items-center gap-3"><button className="hidden rounded-xl p-2.5 text-slate-400 hover:bg-slate-50 sm:block"><Search className="h-5 w-5" /></button><div className="hidden h-8 w-px bg-slate-200 sm:block" /><div className="flex items-center gap-3"><Button onClick={() => setCandidateMode((v) => !v)} variant="outline" size="sm" className="hidden border-slate-200 text-xs text-slate-600 md:flex">{candidateMode ? "管理者へ戻る" : "受験者プレビュー"}</Button><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#dceafb] text-xs font-bold text-[#1d507f]">田中</div><div className="hidden text-left md:block"><p className="text-xs font-bold">田中 美咲</p><p className="text-[11px] text-slate-400">管理者</p></div></div></div>
        </header>
        <nav className="flex gap-1 overflow-x-auto border-b border-slate-200 bg-white px-4 py-2 lg:hidden">{navItems.map((item) => { const Icon = item.icon; const active = activeNav === item.label; return <button key={item.label} onClick={() => setActiveNav(item.label)} className={`flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-xs font-bold ${active ? "bg-[#eaf1f9] text-[#16365f]" : "text-slate-500"}`}><Icon className="h-3.5 w-3.5" />{item.label}</button>; })}</nav>

        <div className="mx-auto max-w-[1440px] px-5 py-7 md:px-9 md:py-9">
          {candidateMode ? <CandidateView onExit={() => setCandidateMode(false)} /> : null}
          {!candidateMode && activeNav === "概要" && <Overview onGenerate={() => setShowGenerator(true)} onUpload={() => setShowUpload(true)} notify={notify} />}
          {!candidateMode && activeNav === "資料ライブラリ" && <MaterialsView search={materialSearch} setSearch={setMaterialSearch} items={filteredMaterials} onUpload={() => setShowUpload(true)} notify={notify} onView={setSelectedMaterial} />}
          {!candidateMode && activeNav === "問題バンク" && <QuestionBank onGenerate={() => setShowGenerator(true)} notify={notify} />}
          {!candidateMode && activeNav === "テスト管理" && <TestsView notify={notify} />}
          {!candidateMode && activeNav === "結果分析" && <AnalyticsView />}
          {!candidateMode && activeNav === "記述採点" && <GradingView notify={notify} />}
          {!candidateMode && activeNav === "使用説明書" && <Guide />}
        </div>
      </main>

      {selectedMaterial && <MaterialDetailModal material={selectedMaterial} onClose={() => setSelectedMaterial(null)} />}
      {showUpload && <UploadModal onClose={() => setShowUpload(false)} onDone={() => { void utils.materials.list.invalidate(); setShowUpload(false); notify("資料を登録しました。AI抽出を開始しています。"); }} />}
      {showGenerator && <AutoGeneratorModal materials={materialItems} generated={generated} setGenerated={setGenerated} onClose={() => { setShowGenerator(false); setGenerated(false); }} onDone={() => { setShowGenerator(false); setGenerated(false); notify("問題案を下書きとして保存しました。"); }} />}
      {toast && <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 rounded-xl bg-[#17365d] px-4 py-3 text-sm font-semibold text-white shadow-xl"><Check className="h-4 w-4 text-emerald-300" />{toast}</div>}
    </div>
  );
}

function Overview({ onGenerate, onUpload }: { onGenerate: () => void; onUpload: () => void; notify: (m: string) => void }) {
  return <div className="space-y-8"><section className="relative overflow-hidden rounded-3xl bg-[#17365d] px-6 py-7 text-white shadow-xl md:px-9 md:py-8"><div className="relative z-10 max-w-2xl"><div className="mb-4 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.16em] text-blue-200"><span className="h-2 w-2 rounded-full bg-emerald-400" />Live workspace</div><h2 className="text-2xl font-bold leading-tight md:text-[30px]">資料を、理解を測る<br /><span className="text-[#a9d1ef]">確かな問い</span>に変える。</h2><p className="mt-4 max-w-xl text-sm leading-6 text-blue-100/75">アップロード資料を唯一の根拠に、AIが問題案を作成します。生成後は管理者が根拠を確認して承認します。</p><div className="mt-6 flex flex-wrap gap-3"><Button onClick={onGenerate} className="bg-white text-[#17365d]"><Sparkles className="mr-2 h-4 w-4" />問題案を生成</Button><Button onClick={onUpload} variant="outline" className="border-white/25 bg-white/10 text-white hover:text-white"><UploadCloud className="mr-2 h-4 w-4" />資料を追加</Button></div></div></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([["登録資料", "0", "まず資料を追加", FolderOpen], ["承認待ち問題", "0", "生成後に確認", FileCheck2], ["公開中テスト", "0", "作成したテストなし", GraduationCap], ["平均合格率", "—", "受験データなし", Target]] as const).map(([label, value, sub, Icon]) => <Card key={label} className="border-0 shadow-sm"><CardContent className="p-5"><p className="text-xs font-semibold text-slate-400">{label}</p><p className="mt-2 text-2xl font-bold text-[#1c304c]">{value}</p><p className="mt-1 text-[11px] text-slate-400">{sub}</p><Icon className="mt-4 h-5 w-5 text-[#3975a8]" /></CardContent></Card>)}</section><div className="grid gap-6 xl:grid-cols-2"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">最近の活動</CardTitle></CardHeader><CardContent><GuideEmptyState title="活動履歴はありません" body="資料登録、問題生成、承認などの操作を行うと、ここに履歴が表示されます。" /></CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">公開中テスト</CardTitle></CardHeader><CardContent><GuideEmptyState title="公開中のテストはありません" body="テストを作成して公開すると、受験状況がここに表示されます。" /></CardContent></Card></div></div>;
}

function MaterialsView({ search, setSearch, items, onUpload, notify, onView }: { search: string; setSearch: (v: string) => void; items: MaterialCard[]; onUpload: () => void; notify: (m: string) => void; onView: (material: MaterialCard) => void }) {
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-sm font-semibold text-[#3975a8]">{items.length}件の資料</p><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">資料ライブラリ</h2><p className="mt-2 text-sm text-slate-500">問題生成に使う資料と、AIが抽出した根拠情報を管理します。</p></div><Button onClick={onUpload} className="w-fit bg-[#17365d] hover:bg-[#214c7c]"><UploadCloud className="mr-2 h-4 w-4" />資料をアップロード</Button></div><div className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="資料名・カテゴリで検索" className="border-0 pl-9 shadow-none focus-visible:ring-0" /></div><Button variant="outline" onClick={() => notify("フィルターを開きます。")} className="border-slate-200 text-slate-600"><Filter className="mr-2 h-4 w-4" />絞り込み</Button></div><div className="grid gap-4 xl:grid-cols-3">{items.map((item) => <Card key={item.title} className="group border-0 shadow-sm shadow-slate-200/70 transition hover:-translate-y-0.5 hover:shadow-md"><CardContent className="p-5"><div className="flex items-start justify-between"><div className={`flex h-11 w-11 items-center justify-center rounded-xl ${item.color === "rose" ? "bg-rose-50 text-rose-500" : item.color === "sky" ? "bg-sky-50 text-sky-500" : "bg-amber-50 text-amber-500"}`}><FileText className="h-5 w-5" /></div><button onClick={() => notify("資料の詳細メニューを開きます。")} className="rounded-lg p-1.5 text-slate-300 hover:bg-slate-50 hover:text-slate-600"><MoreHorizontal className="h-5 w-5" /></button></div><div className="mt-5"><div className="flex items-center gap-2"><h3 className="truncate text-[15px] font-bold text-[#203956]">{item.title}</h3><Badge variant="outline" className="shrink-0 border-slate-200 text-[10px] text-slate-400">{item.type}</Badge></div><div className="mt-2 flex items-center gap-3 text-xs text-slate-400"><span>{item.category}</span><span>·</span><span>{item.pages}ページ</span><span>·</span><span>{item.updated}</span></div><div className="mt-4 flex flex-wrap gap-1.5">{item.keywords.map((k) => <span key={k} className="rounded-md bg-slate-50 px-2 py-1 text-[11px] font-semibold text-slate-500">#{k}</span>)}</div></div><Separator className="my-5 bg-slate-100" /><div className="flex items-center justify-between"><span className={`flex items-center gap-1.5 text-xs font-bold ${item.status === "利用中" ? "text-emerald-600" : "text-slate-400"}`}><span className={`h-1.5 w-1.5 rounded-full ${item.status === "利用中" ? "bg-emerald-500" : "bg-slate-300"}`} />{item.status}</span><Button variant="ghost" size="sm" onClick={() => onView(item)} className="text-xs text-[#3975a8]">抽出情報を見る<ChevronRight className="ml-1 h-3.5 w-3.5" /></Button></div></CardContent></Card>)}<button onClick={onUpload} className="flex min-h-[250px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-200 bg-white/60 text-center transition hover:border-[#9abbd6] hover:bg-[#f7fbff]"><div className="flex h-12 w-12 items-center justify-center rounded-xl bg-[#eaf3fb] text-[#3975a8]"><Plus className="h-5 w-5" /></div><p className="mt-4 text-sm font-bold text-slate-600">資料を追加</p><p className="mt-1 text-xs text-slate-400">PDF / DOCX / PPTX / TXT / CSV / 画像</p></button></div></div>;
}

function QuestionBank({ onGenerate, notify }: { onGenerate: () => void; notify: (m: string) => void }) {
  const { data: questions = [], isLoading } = trpc.questions.list.useQuery();
  const [tab, setTab] = useState<"approved" | "draft" | "rejected">("approved"); const [search, setSearch] = useState(""); const [tag, setTag] = useState("");
  const availableTags = Array.from(new Set(questions.flatMap((question) => Array.isArray(question.tags) ? (question.tags as string[]) : []))).sort(); const filteredQuestions = questions.filter((question) => question.prompt.toLowerCase().includes(search.toLowerCase()) && (!tag || (Array.isArray(question.tags) && (question.tags as string[]).includes(tag))));
  const groups = { approved: filteredQuestions.filter((question) => question.status === "approved"), draft: filteredQuestions.filter((question) => question.status === "draft"), rejected: filteredQuestions.filter((question) => question.status === "rejected") };
  const current = groups[tab];
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-sm font-semibold text-[#b36b35]">{groups.draft.length}件が承認待ち · {groups.rejected.length}件が差し戻し</p><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">問題バンク</h2><p className="mt-2 text-sm text-slate-500">AI生成案は資料の根拠を確認してから承認します。</p></div><Button onClick={onGenerate} className="w-fit bg-[#17365d]"><Sparkles className="mr-2 h-4 w-4" />AIで問題案を生成</Button></div>{isLoading ? <div className="rounded-2xl bg-white p-8 text-sm text-slate-400">問題一覧を読み込んでいます…</div> : <><div className="flex flex-col gap-3 rounded-2xl bg-white p-3 shadow-sm sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="設問文を検索" className="border-0 pl-9 shadow-none focus-visible:ring-0" /></div><select value={tag} onChange={(event) => setTag(event.target.value)} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-sm text-slate-600"><option value="">すべてのタグ</option>{availableTags.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="flex flex-wrap gap-2 rounded-2xl bg-white p-2 shadow-sm">{([['approved', '承認済み', groups.approved.length], ['draft', '承認待ち', groups.draft.length], ['rejected', '差し戻し', groups.rejected.length] ] as const).map(([value, label, count]) => <button key={value} onClick={() => setTab(value)} className={`rounded-xl px-4 py-2 text-xs font-bold transition ${tab === value ? "bg-[#17365d] text-white" : "text-slate-500 hover:bg-slate-50"}`}>{label} <span className="ml-1 opacity-70">{count}</span></button>)}</div><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">{tab === "approved" ? "承認済み問題" : tab === "draft" ? "承認待ち問題" : "差し戻し問題"}</CardTitle></CardHeader><CardContent className="p-0">{current.length === 0 ? <GuideEmptyState title={tab === "approved" ? "承認済み問題はまだありません" : tab === "draft" ? "承認待ちの問題はありません" : "差し戻し問題はありません"} body="資料を登録してから問題案を生成してください。" /> : current.map((question) => <div key={question.id} className="flex flex-col gap-3 border-b border-slate-100 px-6 py-5 last:border-0 md:flex-row md:items-center"><div className="min-w-0 flex-1"><p className="text-sm font-semibold leading-5 text-slate-700">{question.prompt}</p><p className="mt-1 text-xs text-slate-400">{question.type} · {question.difficulty} · {question.points}点 · 根拠 {Array.isArray(question.evidence) ? question.evidence.length : 0}件</p></div><Badge variant="outline" className="w-fit text-[10px]">{question.status}</Badge></div>)}</CardContent></Card></>}</div>;
}

function TestsView({ notify }: { notify: (m: string) => void }) {
  const { data: tests = [], isLoading } = trpc.tests.list.useQuery(); const { data: materials = [] } = trpc.materials.list.useQuery(); const { data: questions = [] } = trpc.questions.list.useQuery(); const utils = trpc.useUtils(); const create = trpc.tests.create.useMutation({ onSuccess: async () => { await utils.tests.list.invalidate(); setOpen(false); notify("テストを下書き保存しました。"); } }); const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [questionCount, setQuestionCount] = useState(10); const [passScore, setPassScore] = useState(70); const [timeLimitMinutes, setTimeLimitMinutes] = useState(30); const [attemptLimit, setAttemptLimit] = useState(1); const [accessMode, setAccessMode] = useState<"closed" | "specified" | "timed">("closed"); const [revealMode, setRevealMode] = useState<"immediate" | "after_submit" | "after_period">("after_submit"); const [targetMaterialIds, setTargetMaterialIds] = useState<number[]>([]); const [targetQuestionIds, setTargetQuestionIds] = useState<number[]>([]); const [formatDistribution, setFormatDistribution] = useState("single:5,comparison:3,short_answer:2"); const [difficultyDistribution, setDifficultyDistribution] = useState("basic:3,standard:5,advanced:2"); const [availableFrom, setAvailableFrom] = useState(""); const [availableUntil, setAvailableUntil] = useState("");
  const parseDistribution = (value: string) => Object.fromEntries(value.split(",").map((part) => part.trim().split(":")).filter(([key, amount]) => key && amount && !Number.isNaN(Number(amount))).map(([key, amount]) => [key, Number(amount)]));
  const submit = () => { if (!name.trim()) return; create.mutate({ name, description, questionCount, passScore, timeLimitMinutes, attemptLimit, accessMode, revealMode, targetMaterialIds, targetQuestionIds, formatDistribution: parseDistribution(formatDistribution), difficultyDistribution: parseDistribution(difficultyDistribution), availableFrom: availableFrom ? new Date(availableFrom) : null, availableUntil: availableUntil ? new Date(availableUntil) : null }); };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-sm font-semibold text-[#4b7e68]">{tests.length}件のテスト</p><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">テスト管理</h2><p className="mt-2 text-sm text-slate-500">出題配分、閲覧モード、受験条件を設定します。</p></div><Button onClick={() => setOpen((value) => !value)} className="w-fit bg-[#17365d]"><Plus className="mr-2 h-4 w-4" />{open ? "作成フォームを閉じる" : "テストを作成"}</Button></div>{open && <Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">テスト設定を下書き保存</CardTitle></CardHeader><CardContent className="space-y-4"><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-bold text-slate-600">テスト名<Input value={name} onChange={(event) => setName(event.target.value)} className="mt-2" placeholder="例：新任研修 理解度確認" /></label><label className="text-xs font-bold text-slate-600">説明文<Input value={description} onChange={(event) => setDescription(event.target.value)} className="mt-2" /></label></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label className="text-xs font-bold text-slate-600">出題数<Input type="number" min={1} value={questionCount} onChange={(event) => setQuestionCount(Number(event.target.value))} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">合格基準（%）<Input type="number" min={0} max={100} value={passScore} onChange={(event) => setPassScore(Number(event.target.value))} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">制限時間（分）<Input type="number" min={1} value={timeLimitMinutes} onChange={(event) => setTimeLimitMinutes(Number(event.target.value))} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">受験可能回数<Input type="number" min={1} value={attemptLimit} onChange={(event) => setAttemptLimit(Number(event.target.value))} className="mt-2" /></label></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-bold text-slate-600">資料閲覧モード<select value={accessMode} onChange={(event) => setAccessMode(event.target.value as typeof accessMode)} className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="closed">資料閲覧不可</option><option value="specified">指定資料のみ閲覧可</option><option value="timed">時間制限付き閲覧</option></select></label><label className="text-xs font-bold text-slate-600">正答・解説の公開<select value={revealMode} onChange={(event) => setRevealMode(event.target.value as typeof revealMode)} className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="immediate">即時公開</option><option value="after_submit">提出後に公開</option><option value="after_period">受験期間終了後</option></select></label></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-bold text-slate-600">形式別配分<Input value={formatDistribution} onChange={(event) => setFormatDistribution(event.target.value)} className="mt-2" /><span className="mt-1 block text-[11px] font-normal text-slate-400">例: single:5,comparison:3</span></label><label className="text-xs font-bold text-slate-600">難易度別配分<Input value={difficultyDistribution} onChange={(event) => setDifficultyDistribution(event.target.value)} className="mt-2" /><span className="mt-1 block text-[11px] font-normal text-slate-400">例: basic:3,standard:5,advanced:2</span></label></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-bold text-slate-600">受験開始日時<Input type="datetime-local" value={availableFrom} onChange={(event) => setAvailableFrom(event.target.value)} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">受験終了日時<Input type="datetime-local" value={availableUntil} onChange={(event) => setAvailableUntil(event.target.value)} className="mt-2" /></label></div><div className="grid gap-4 md:grid-cols-2"><div><p className="text-xs font-bold text-slate-600">対象資料</p><div className="mt-2 max-h-28 space-y-2 overflow-auto rounded-xl border border-slate-200 p-3">{materials.map((material) => <label key={material.id} className="flex items-center gap-2 text-xs text-slate-600"><input type="checkbox" checked={targetMaterialIds.includes(material.id)} onChange={() => setTargetMaterialIds((current) => current.includes(material.id) ? current.filter((id) => id !== material.id) : [...current, material.id])} />{material.title}</label>)}{!materials.length && <p className="text-xs text-slate-400">資料がありません</p>}</div></div><div><p className="text-xs font-bold text-slate-600">対象問題</p><div className="mt-2 max-h-28 space-y-2 overflow-auto rounded-xl border border-slate-200 p-3">{questions.filter((question) => question.status === "approved").map((question) => <label key={question.id} className="flex items-start gap-2 text-xs text-slate-600"><input type="checkbox" checked={targetQuestionIds.includes(question.id)} onChange={() => setTargetQuestionIds((current) => current.includes(question.id) ? current.filter((id) => id !== question.id) : [...current, question.id])} /><span>{question.prompt}</span></label>)}{!questions.some((question) => question.status === "approved") && <p className="text-xs text-slate-400">承認済み問題がありません</p>}</div></div></div><div className="flex justify-end"><Button onClick={submit} disabled={!name.trim() || create.isPending} className="bg-[#17365d]">{create.isPending ? "保存中…" : "下書き保存"}</Button></div></CardContent></Card>}{isLoading ? <div className="rounded-2xl bg-white p-8 text-sm text-slate-400">テスト一覧を読み込んでいます…</div> : tests.length === 0 ? <GuideEmptyState title="テストはまだありません" body="承認済みの問題を登録してから、テストを作成してください。" /> : <div className="grid gap-4 lg:grid-cols-2">{tests.map((test) => <Card key={test.id} className="border-0 shadow-sm"><CardContent className="p-6"><div className="flex items-start justify-between"><div><h3 className="font-bold text-[#203956]">{test.name}</h3><p className="mt-1 text-xs text-slate-400">全{test.questionCount}問 · {test.timeLimitMinutes}分 · 合格基準{test.passScore}%</p></div><Badge variant="outline" className="text-[10px]">{test.status}</Badge></div><Separator className="my-5" /><Button variant="ghost" size="sm" onClick={() => notify(`${test.name}の詳細設定を開きます。`)} className="text-[#3975a8]">設定を開く<ChevronRight className="ml-1 h-3.5 w-3.5" /></Button></CardContent></Card>)}</div>}</div>;
}

function AnalyticsView() {
  const { data, isLoading } = trpc.analytics.summary.useQuery({});
  const { refetch: fetchCsv } = trpc.analytics.csv.useQuery({}, { enabled: false });
  const attempts = data?.attempts ?? [];
  const downloadCsv = async () => { const result = await fetchCsv(); if (!result.data) return; const blob = new Blob([result.data], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "sourcebound-results.csv"; anchor.click(); URL.revokeObjectURL(url); };
  const submitted = attempts.filter((attempt) => attempt.status === "submitted");
  const average = submitted.length ? Math.round(submitted.reduce((sum, attempt) => sum + Number(attempt.score ?? 0), 0) / submitted.length) : null;
  return <div className="space-y-6"><div><p className="text-sm font-semibold text-[#725d9b]">受験データ</p><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">結果分析</h2><p className="mt-2 text-sm text-slate-500">問題・資料・分野ごとの理解度と受験行動を確認できます。</p></div><Button onClick={downloadCsv} variant="outline" className="w-fit border-slate-200 text-xs">CSVをダウンロード</Button></div></div>{isLoading ? <div className="rounded-2xl bg-white p-8 text-sm text-slate-400">分析データを読み込んでいます…</div> : <><div className="grid gap-4 sm:grid-cols-3"><Card className="border-0 shadow-sm"><CardContent className="p-5"><p className="text-xs font-semibold text-slate-400">受験件数</p><p className="mt-2 text-3xl font-bold text-[#253e5e]">{attempts.length}</p></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="p-5"><p className="text-xs font-semibold text-slate-400">提出済み</p><p className="mt-2 text-3xl font-bold text-[#253e5e]">{submitted.length}</p></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="p-5"><p className="text-xs font-semibold text-slate-400">平均得点</p><p className="mt-2 text-3xl font-bold text-[#253e5e]">{average === null ? "—" : average}</p></CardContent></Card></div>{attempts.length === 0 ? <GuideEmptyState title="分析データはまだありません" body="受験者がテストを提出すると、得点、正答率、回答時間、行動記録がここに表示されます。" /> : <div className="grid gap-6 xl:grid-cols-2"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">問題形式別正答率</CardTitle></CardHeader><CardContent className="space-y-3">{(data?.byFormat ?? []).map((row) => <div key={row.type} className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 text-sm"><span className="text-slate-600">{row.type}</span><span className="font-bold text-[#3975a8]">{row.correctRate}% · {row.responseCount}回答</span></div>)}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">問題別正答率・回答時間</CardTitle></CardHeader><CardContent className="space-y-3">{(data?.byQuestion ?? []).map((row) => <div key={row.questionId} className="rounded-xl bg-slate-50 px-4 py-3 text-sm"><div className="flex items-center justify-between gap-3"><span className="truncate text-slate-600">問題 #{row.questionId}</span><span className="font-bold text-[#3975a8]">{row.correctRate}% · {row.responseCount}回答</span></div><p className="mt-1 text-xs text-slate-400">平均回答時間：{row.averageTimeMs ? `${Math.round(row.averageTimeMs / 1000)}秒` : "—"}</p></div>)}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">分野別正答率</CardTitle></CardHeader><CardContent className="space-y-3">{(data?.byDomain ?? []).length === 0 ? <p className="text-sm text-slate-400">問題タグを設定すると分野別に集計できます。</p> : (data?.byDomain ?? []).map((row) => <div key={row.tag} className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 text-sm"><span className="text-slate-600">{row.tag}</span><span className="font-bold text-[#3975a8]">{row.correctRate}% · {row.responseCount}回答</span></div>)}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">資料別正答率</CardTitle></CardHeader><CardContent className="space-y-3">{(data?.byMaterial ?? []).map((row) => <div key={row.materialId} className="flex items-center justify-between rounded-xl bg-slate-50 px-4 py-3 text-sm"><span className="truncate text-slate-600">{row.title}</span><span className="font-bold text-[#3975a8]">{row.correctRate}%</span></div>)}</CardContent></Card></div>}</>}</div>;
}
function GradingView({ notify }: { notify: (message: string) => void }) {
  const { data: items = [], isLoading, isError } = trpc.attempts.pendingShortAnswers.useQuery(); const utils = trpc.useUtils(); const grade = trpc.attempts.gradeShortAnswer.useMutation({ onSuccess: async () => { await utils.attempts.pendingShortAnswers.invalidate(); notify("採点結果とコメントを保存しました。"); } }); const [scores, setScores] = useState<Record<number, { conclusion: number; evidence: number; logic: number; comment: string }>>({}); const update = (id: number, key: "conclusion" | "evidence" | "logic" | "comment", value: number | string) => setScores((current) => ({ ...current, [id]: { conclusion: current[id]?.conclusion ?? 0, evidence: current[id]?.evidence ?? 0, logic: current[id]?.logic ?? 0, comment: current[id]?.comment ?? "", [key]: value } })); return <div className="space-y-6"><div><p className="text-sm font-semibold text-[#725d9b]">採点者ワークスペース</p><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">記述採点</h2><p className="mt-2 text-sm text-slate-500">結論・資料根拠・論理性を各0〜4点で評価し、コメントを保存します。</p></div>{isError ? <div className="rounded-2xl bg-rose-50 p-8 text-sm text-rose-700">採点対象の取得に失敗しました。権限と接続を確認して再読み込みしてください。</div> : isLoading ? <div className="rounded-2xl bg-white p-8 text-sm text-slate-400">未採点の記述回答を読み込んでいます…</div> : items.length === 0 ? <GuideEmptyState title="未採点の記述回答はありません" body="受験者が短文記述問題を提出すると、ここに採点対象が表示されます。" /> : <div className="space-y-4">{items.map((item) => { const score = scores[item.id] ?? { conclusion: 0, evidence: 0, logic: 0, comment: "" }; return <Card key={item.id} className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#203956]">問題 #{item.questionId}</CardTitle><p className="text-xs text-slate-400">{item.question?.prompt}</p></CardHeader><CardContent className="space-y-4"><div className="rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-600">{String(item.answer ?? "（未回答）")}</div><div className="grid gap-3 sm:grid-cols-3">{([['conclusion', '結論'], ['evidence', '資料根拠'], ['logic', '論理性']] as const).map(([key, label]) => <label key={key} className="text-xs font-bold text-slate-600">{label}<Input type="number" min={0} max={4} value={score[key]} onChange={(event) => update(item.id, key, Number(event.target.value))} className="mt-2" /></label>)}</div><Textarea value={score.comment} onChange={(event) => update(item.id, "comment", event.target.value)} placeholder="採点者コメント" /><div className="flex justify-end gap-3">{grade.isError && <p className="self-center text-xs text-rose-600">保存に失敗しました。再試行してください。</p>}<Button onClick={() => grade.mutate({ attemptId: item.attemptId, questionId: item.questionId, conclusion: score.conclusion, evidence: score.evidence, logic: score.logic, comment: score.comment })} disabled={grade.isPending} className="bg-[#17365d]">採点結果を保存</Button></div></CardContent></Card>; })}</div>}</div>;
}

function CandidateView({ onExit }: { onExit: () => void }) {
  const { data: tests = [], isLoading: testsLoading } = trpc.tests.list.useQuery();
  const { data: questionRows = [], isLoading: questionsLoading } = trpc.questions.list.useQuery(); const { data: materialRows = [] } = trpc.materials.list.useQuery();
  const start = trpc.attempts.start.useMutation();
  const saveAnswer = trpc.attempts.saveAnswer.useMutation();
  const logEvent = trpc.attempts.event.useMutation();
  const submit = trpc.attempts.submit.useMutation();
  const publishedTests = tests.filter((test) => test.status === "published");
  const approvedQuestions = questionRows.filter((question) => question.status === "approved");
  const [started, setStarted] = useState(false); const [attemptId, setAttemptId] = useState<number | null>(null); const [order, setOrder] = useState<number[]>([]); const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<Record<number, unknown>>({}); const [seconds, setSeconds] = useState(0); const [submitted, setSubmitted] = useState(false); const [score, setScore] = useState<number | null>(null); const [materialSearch, setMaterialSearch] = useState(""); const [materialPage, setMaterialPage] = useState(1); const [materialZoom, setMaterialZoom] = useState(100); const [materialSeconds, setMaterialSeconds] = useState(120);
  const test = publishedTests[0];
  const questions = order.map((id) => questionRows.find((question) => question.id === id)).filter(Boolean) as typeof questionRows;
  const q = questions[index];
  useEffect(() => { if (!started || submitted) return; const timer = window.setInterval(() => setSeconds((value) => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [started, submitted]); useEffect(() => { if (!started || submitted || test?.accessMode !== "timed") return; const timer = window.setInterval(() => setMaterialSeconds((value) => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [started, submitted, test?.accessMode]);
  const begin = async () => { if (!test) return; const result = await start.mutateAsync({ testId: test.id, questionIds: approvedQuestions.map((question) => question.id).slice(0, test.questionCount), recentQuestionIds: [] }); setAttemptId(result.attemptId); setOrder(result.questionIds); setSeconds(test.timeLimitMinutes * 60); setStarted(true); };
  const answer = (value: unknown) => { if (!q) return; setAnswers((current) => ({ ...current, [q.id]: value })); if (attemptId) { void saveAnswer.mutateAsync({ attemptId, questionId: q.id, answer: value }); void logEvent.mutateAsync({ attemptId, questionId: q.id, eventType: "answer_change" }); } };
  const finish = async () => { if (!attemptId || submitted) return; const result = await submit.mutateAsync({ attemptId, answers: Object.entries(answers).map(([questionId, value]) => ({ questionId: Number(questionId), answer: value })) }); await logEvent.mutateAsync({ attemptId, eventType: "submit" }); setScore(result.score); setSubmitted(true); };
  useEffect(() => { if (started && !submitted && seconds === 0) void finish(); }, [seconds, started, submitted]);
  if (testsLoading || questionsLoading) return <div className="rounded-2xl bg-white p-8 text-sm text-slate-400">受験可能なテストを確認しています…</div>;
  if (!test || !approvedQuestions.length) return <div className="space-y-5"><GuideEmptyState title="受験可能なテストはありません" body="管理者が公開したテストと承認済み問題が登録されると、ここから受験できます。" /><Button variant="outline" onClick={onExit}>管理画面へ戻る</Button></div>;
  if (!started) return <Card className="mx-auto max-w-2xl border-0 shadow-sm"><CardContent className="p-8"><Badge className="bg-[#eef4fa] text-[#3975a8]">受験者プレビュー</Badge><h2 className="mt-4 text-2xl font-bold text-[#1b3453]">{test.name}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{test.description || "公開された資料根拠型テストです。"}</p><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-400">問題数</p><p className="mt-1 text-lg font-bold text-[#203956]">{Math.min(test.questionCount, approvedQuestions.length)}問</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-400">制限時間</p><p className="mt-1 text-lg font-bold text-[#203956]">{test.timeLimitMinutes}分</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-400">合格基準</p><p className="mt-1 text-lg font-bold text-[#203956]">{test.passScore}%</p></div></div><div className="mt-7 flex justify-end gap-3"><Button variant="outline" onClick={onExit}>戻る</Button><Button onClick={begin} disabled={start.isPending} className="bg-[#17365d]">{start.isPending ? "準備中…" : "受験を開始"}</Button></div></CardContent></Card>;
  if (submitted) return <Card className="mx-auto max-w-2xl border-0 shadow-sm"><CardContent className="p-12 text-center"><Check className="mx-auto h-10 w-10 text-emerald-600" /><h2 className="mt-4 text-xl font-bold text-[#203956]">提出を受け付けました</h2><p className="mt-2 text-sm text-slate-500">選択式問題は自動採点され、記述式問題は採点者の確認後に結果が公開されます。</p>{score !== null && <p className="mt-4 text-2xl font-bold text-[#3975a8]">自動採点スコア: {score}点</p>}<Button onClick={onExit} className="mt-6 bg-[#17365d]">管理画面へ戻る</Button></CardContent></Card>;
  if (!q) return null;
  const minutes = String(Math.floor(seconds / 60)).padStart(2, "0"); const secs = String(seconds % 60).padStart(2, "0"); const options = Array.isArray(q.options) ? q.options as string[] : [];
  const allowedMaterials = materialRows.filter((material) => test.accessMode !== "specified" || (Array.isArray(test.targetMaterialIds) && (test.targetMaterialIds as number[]).includes(material.id))).filter((material) => material.title.toLowerCase().includes(materialSearch.toLowerCase())); const activeMaterial = allowedMaterials[0];
  return <div className="mx-auto max-w-6xl space-y-5"><div className="flex items-center justify-between"><div><p className="text-xs font-bold text-[#3975a8]">受験者プレビュー · {test.name}</p><h2 className="mt-1 text-2xl font-bold text-[#1b3453]">{index + 1} / {questions.length}問</h2></div><div className="rounded-xl bg-white px-4 py-2 text-center shadow-sm"><p className="text-[10px] font-bold text-slate-400">残り時間</p><p className="font-mono text-lg font-bold text-[#17365d]">{minutes}:{secs}</p></div></div><div className="h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-[#3975a8]" style={{ width: `${((index + 1) / questions.length) * 100}%` }} /></div>{test.accessMode !== "closed" && (test.accessMode === "specified" || materialSeconds > 0) && <Card className="border-0 shadow-sm"><CardContent className="space-y-3 p-4"><div className="flex flex-col gap-2 sm:flex-row sm:items-center"><span className="text-sm font-bold text-[#203956]">許可資料{test.accessMode === "timed" && <span className="ml-2 text-xs font-normal text-amber-600">残り{materialSeconds}秒</span>}</span><Input value={materialSearch} onChange={(event) => setMaterialSearch(event.target.value)} placeholder="資料名を検索" className="sm:ml-auto sm:max-w-xs" /><div className="flex items-center gap-1"><Button size="sm" variant="outline" onClick={() => setMaterialZoom((value) => Math.max(70, value - 10))}>−</Button><span className="w-12 text-center text-xs text-slate-500">{materialZoom}%</span><Button size="sm" variant="outline" onClick={() => setMaterialZoom((value) => Math.min(150, value + 10))}>＋</Button></div></div>{activeMaterial ? <div className="rounded-xl bg-slate-50 p-4"><div className="flex items-center justify-between text-xs text-slate-500"><span>{activeMaterial.title}</span><span>ページ {materialPage} / {Math.max(1, activeMaterial.pageCount)}</span></div><p className="mt-3 max-h-32 overflow-auto whitespace-pre-wrap text-sm leading-6 text-slate-600" style={{ fontSize: `${materialZoom / 100}rem` }}>{activeMaterial.extractedText || "抽出本文はありません。資料の根拠情報を確認してください。"}</p><div className="mt-3 flex justify-end gap-2"><Button size="sm" variant="outline" disabled={materialPage <= 1} onClick={() => setMaterialPage((value) => value - 1)}>前ページ</Button><Button size="sm" variant="outline" disabled={materialPage >= activeMaterial.pageCount} onClick={() => setMaterialPage((value) => value + 1)}>次ページ</Button></div></div> : <p className="text-sm text-slate-400">閲覧可能な資料はありません。</p>}</CardContent></Card>}<Card className="border-0 shadow-sm"><CardContent className="p-6 md:p-9"><Badge className="bg-[#eef4fa] text-[#3975a8]">{q.type} · {q.difficulty}</Badge><h3 className="mt-6 text-lg font-bold leading-8 text-[#203956]">{q.prompt}</h3>{options.length ? <div className="mt-7 space-y-3">{options.map((option) => <button key={option} onClick={() => answer(option)} className={`flex w-full items-start gap-3 rounded-xl border p-4 text-left text-sm ${answers[q.id] === option ? "border-[#74a8ca] bg-[#f0f7fc]" : "border-slate-200"}`}>{option}</button>)}</div> : <Textarea value={String(answers[q.id] ?? "")} onChange={(event) => answer(event.target.value)} className="mt-7 min-h-[150px]" placeholder="資料の根拠を含めて入力してください" />}<div className="mt-8 flex justify-between"><Button variant="outline" disabled={index === 0} onClick={() => setIndex((value) => value - 1)}>前の問題</Button>{index < questions.length - 1 ? <Button onClick={() => setIndex((value) => value + 1)} className="bg-[#17365d]">次の問題<ChevronRight className="ml-2 h-4 w-4" /></Button> : <Button onClick={finish} disabled={submit.isPending} className="bg-[#2f765d]">{submit.isPending ? "提出中…" : "提出する"}<Check className="ml-2 h-4 w-4" /></Button>}</div></CardContent></Card></div>;
}

function MaterialDetailModal({ material, onClose }: { material: MaterialCard; onClose: () => void }) { return <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#0d2139]/45 p-4 backdrop-blur-sm"><Card className="max-h-[90vh] w-full max-w-3xl overflow-y-auto border-0 shadow-2xl"><CardHeader className="flex-row items-start justify-between"><div><CardTitle className="text-xl text-[#1b3453]">{material.title}</CardTitle><p className="mt-1 text-xs text-slate-400">{material.type} · {material.pages}ページ · {material.category}</p></div><button onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"><X className="h-5 w-5" /></button></CardHeader><CardContent className="space-y-5"><div><p className="text-xs font-bold text-slate-500">見出し</p><div className="mt-2 flex flex-wrap gap-2">{material.headings.length ? material.headings.map((heading) => <Badge key={heading} variant="outline">{heading}</Badge>) : <p className="text-sm text-slate-400">抽出された見出しはありません。</p>}</div></div><div><p className="text-xs font-bold text-slate-500">重要キーワード</p><div className="mt-2 flex flex-wrap gap-2">{material.keywords.length ? material.keywords.map((keyword) => <span key={keyword} className="rounded-md bg-slate-50 px-2 py-1 text-xs text-slate-600">#{keyword}</span>) : <p className="text-sm text-slate-400">キーワードはありません。</p>}</div></div><div><p className="text-xs font-bold text-slate-500">本文</p><div className="mt-2 max-h-64 overflow-auto rounded-xl bg-slate-50 p-4 text-sm leading-7 text-slate-600">{material.text || "抽出本文はありません。画像資料はAI抽出結果をご確認ください。"}</div></div><div><p className="text-xs font-bold text-slate-500">図表・数値の説明</p><div className="mt-2 space-y-2">{material.figureDescriptions.length ? material.figureDescriptions.map((description) => <p key={description} className="rounded-xl border border-slate-100 p-3 text-sm text-slate-600">{description}</p>) : <p className="text-sm text-slate-400">図表説明はありません。</p>}</div></div></CardContent></Card></div>; }

function UploadModal({ onClose, onDone }: { onClose: () => void; onDone: () => void }) {
  const [file, setFile] = useState<File | null>(null); const [category, setCategory] = useState("教材"); const [importance, setImportance] = useState("medium"); const [errorKind, setErrorKind] = useState<"unsupported" | "size" | "extract" | "">("");
  const upload = trpc.materials.uploadAndExtract.useMutation({ onSuccess: onDone, onError: () => setErrorKind("extract") });
  const submit = async () => { if (!file) return; const extension = file.name.split(".").pop()?.toLowerCase() ?? ""; const allowed = ["pdf", "docx", "pptx", "txt", "md", "csv", "png", "jpg", "jpeg"]; if (!allowed.includes(extension)) { setErrorKind("unsupported"); return; } if (file.size > 50 * 1024 * 1024) { setErrorKind("size"); return; } setErrorKind(""); const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1] || ""); reader.onerror = reject; reader.readAsDataURL(file); }); upload.mutate({ fileName: file.name, mimeType: file.type || "application/octet-stream", base64, category: category as "教材" | "マニュアル" | "規程" | "ケース記録" | "参考資料", importance: importance as "high" | "medium" | "low" }); };
  const retry = () => { upload.reset(); setErrorKind(""); void submit(); };
  const errorMessage = errorKind === "unsupported" ? "未対応の形式です。PDF、DOCX、PPTX、TXT、MD、CSV、PNG、JPGを選択してください。" : errorKind === "size" ? "ファイルサイズが50MBを超えています。小さいファイルを選択してください。" : errorKind === "extract" || upload.error ? "資料の抽出に失敗しました。内容を確認して再試行してください。" : "";
  return <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#0d2139]/45 p-4 backdrop-blur-sm"><Card className="w-full max-w-xl border-0 shadow-2xl"><CardHeader className="flex-row items-start justify-between"><div><CardTitle className="text-xl text-[#1b3453]">資料をアップロード</CardTitle><p className="mt-1 text-sm text-slate-400">AIが本文・見出し・キーワード・図表説明を抽出します。</p></div><button onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"><X className="h-5 w-5" /></button></CardHeader><CardContent className="space-y-5"><label className="flex cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-[#b7d0e5] bg-[#f7fbff] px-6 py-10 text-center hover:bg-[#f0f8ff]"><input type="file" className="hidden" accept=".pdf,.docx,.pptx,.txt,.md,.csv,.png,.jpg,.jpeg" onChange={(e) => { setFile(e.target.files?.[0] ?? null); setErrorKind(""); }} /><UploadCloud className="h-8 w-8 text-[#3975a8]" /><p className="mt-3 text-sm font-bold text-[#2a5278]">{file ? file.name : "ファイルをドロップ、またはクリックして選択"}</p><p className="mt-1 text-xs text-slate-400">最大50MB · PDF / DOCX / PPTX / TXT / CSV / PNG / JPG</p></label><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-slate-600">カテゴリ<select value={category} onChange={(e) => setCategory(e.target.value)} className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal"><option>教材</option><option>マニュアル</option><option>規程</option><option>ケース記録</option><option>参考資料</option></select></label><label className="text-xs font-bold text-slate-600">重要度<select value={importance} onChange={(e) => setImportance(e.target.value)} className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal"><option value="medium">標準</option><option value="high">高</option><option value="low">低</option></select></label></div>{errorMessage && <div className="flex flex-col gap-3 rounded-xl bg-rose-50 px-4 py-3 text-xs text-rose-700 sm:flex-row sm:items-center sm:justify-between"><span>{errorMessage}</span><Button type="button" size="sm" variant="outline" onClick={retry} disabled={!file || upload.isPending} className="border-rose-200 text-rose-700">再試行</Button></div>}<div className="flex justify-end gap-3"><Button variant="outline" onClick={onClose}>キャンセル</Button><Button onClick={submit} disabled={!file || upload.isPending} className="bg-[#17365d] hover:bg-[#214c7c]">{upload.isPending ? "抽出中…" : "登録してAI抽出"}</Button></div></CardContent></Card></div>;
}

function AutoGeneratorModal({ materials, generated, setGenerated, onClose, onDone }: { materials: MaterialCard[]; generated: boolean; setGenerated: (v: boolean) => void; onClose: () => void; onDone: () => void }) {
  const [count, setCount] = useState(5);
  const [difficulty, setDifficulty] = useState<"basic" | "standard" | "advanced">("standard");
  const [selected, setSelected] = useState<string[]>(materials[0] ? [materials[0].title] : []);
  const [selectedTypes, setSelectedTypes] = useState<string[]>(["single", "comparison", "short_answer"]);
  const [drafts, setDrafts] = useState<any[]>([]);
  const [resultIds, setResultIds] = useState<number[]>([]);
  const [saveMessage, setSaveMessage] = useState("");
  const generate = trpc.questions.generateDraft.useMutation({ onSuccess: (data) => { setDrafts((data.questions as any[]).map((question) => ({ ...question, difficulty: question.difficulty ?? difficulty }))); setResultIds(data.ids); setGenerated(true); } });
  const utils = trpc.useUtils();
  const edit = trpc.questions.edit.useMutation();
  const review = trpc.questions.review.useMutation();
  const hold = async (index: number) => { await edit.mutateAsync({ id: resultIds[index], type: drafts[index].type ?? "single", difficulty: drafts[index].difficulty ?? "standard", prompt: drafts[index].prompt, options: drafts[index].options ?? [], answer: drafts[index].answer, explanation: drafts[index].explanation, evidence: drafts[index].evidence ?? [], tags: drafts[index].tags ?? [], points: Number(drafts[index].points) || 10 }); await review.mutateAsync({ id: resultIds[index], status: "draft" }); updateDraft(index, { _held: true }); };
  const reject = async (index: number) => { await edit.mutateAsync({ id: resultIds[index], type: drafts[index].type ?? "single", difficulty: drafts[index].difficulty ?? "standard", prompt: drafts[index].prompt, options: drafts[index].options ?? [], answer: drafts[index].answer, explanation: drafts[index].explanation, evidence: drafts[index].evidence ?? [], tags: drafts[index].tags ?? [], points: Number(drafts[index].points) || 10 }); await review.mutateAsync({ id: resultIds[index], status: "rejected" }); updateDraft(index, { _rejected: true }); };
  const labels: Record<string, string> = { single: "四択", multi: "複数選択", true_false: "正誤", ordering: "優先順位", numeric: "数値読解", comparison: "資料比較", short_answer: "短文記述" };
  const toggle = (value: string, list: string[], setter: (next: string[]) => void) => setter(list.includes(value) ? list.filter((item) => item !== value) : [...list, value]);
  const updateDraft = (index: number, patch: Record<string, unknown>) => setDrafts((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item));
  const run = () => { const source = materials.filter((item) => selected.includes(item.title)).map((item) => ({ title: item.title, text: item.text, page: item.pages })); generate.mutate({ materials: source, count, difficulty, types: selectedTypes as any }); };
  const saveAll = async () => { await Promise.all(drafts.map((draft, index) => edit.mutateAsync({ id: resultIds[index], type: draft.type ?? "single", difficulty: draft.difficulty ?? "standard", prompt: draft.prompt, options: draft.options ?? [], answer: draft.answer, explanation: draft.explanation, evidence: draft.evidence ?? [], tags: draft.tags ?? [], points: Number(draft.points) || 10 }))); await utils.questions.list.invalidate(); setSaveMessage(`編集内容を保存しました。難易度: ${drafts.map((draft) => draft.difficulty ?? "standard").join(" / ")}`); };
  const approveOne = async (index: number) => { await edit.mutateAsync({ id: resultIds[index], type: drafts[index].type ?? "single", difficulty: drafts[index].difficulty ?? "standard", prompt: drafts[index].prompt, options: drafts[index].options ?? [], answer: drafts[index].answer, explanation: drafts[index].explanation, evidence: drafts[index].evidence ?? [], tags: drafts[index].tags ?? [], points: Number(drafts[index].points) || 10 }); await review.mutateAsync({ id: resultIds[index], status: "approved" }); await utils.questions.list.invalidate(); updateDraft(index, { _approved: true }); };
  return <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#0d2139]/45 p-4"><Card className="max-h-[94vh] w-full max-w-4xl overflow-y-auto border-0 shadow-2xl"><CardHeader className="flex-row items-start justify-between"><div><div className="flex items-center gap-2"><Sparkles className="h-5 w-5 text-[#c2773b]" /><CardTitle className="text-xl text-[#1b3453]">資料ベース問題生成</CardTitle></div><p className="mt-1 text-sm text-slate-400">生成後に内容を編集し、確認した問題だけを承認できます。</p></div><button onClick={onClose} className="rounded-lg p-1.5 text-slate-400"><X className="h-5 w-5" /></button></CardHeader><CardContent className="space-y-5">{!generated ? <div className="space-y-5"><div><p className="mb-2 text-xs font-bold text-slate-600">使用する資料</p><div className="space-y-2">{materials.map((item) => <label key={item.title} className="flex items-center gap-3 rounded-xl border border-slate-200 p-3"><input type="checkbox" checked={selected.includes(item.title)} onChange={() => toggle(item.title, selected, setSelected)} className="h-4 w-4 accent-[#17365d]" /><FileText className="h-4 w-4 text-[#3975a8]" /><span className="flex-1 text-sm font-semibold text-slate-700">{item.title}</span><span className="text-xs text-slate-400">{item.pages}ページ</span></label>)}</div></div><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-slate-600">問題数<Input type="number" min={1} max={20} value={count} onChange={(e) => setCount(Number(e.target.value))} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">難易度<select value={difficulty} onChange={(e) => setDifficulty(e.target.value as typeof difficulty)} className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="basic">基礎中心</option><option value="standard">標準中心</option><option value="advanced">上級中心</option></select></label></div><div><p className="mb-2 text-xs font-bold text-slate-600">問題形式</p><div className="flex flex-wrap gap-2">{Object.entries(labels).map(([key, label]) => <button key={key} type="button" onClick={() => toggle(key, selectedTypes, setSelectedTypes)} className={`rounded-lg border px-3 py-2 text-xs font-semibold ${selectedTypes.includes(key) ? "border-[#9fc1da] bg-[#eef6fc] text-[#2c638f]" : "border-slate-200 text-slate-500"}`}>{label}</button>)}</div></div><div className="flex justify-end gap-3"><Button variant="outline" onClick={onClose}>キャンセル</Button><Button disabled={!selected.length || !selectedTypes.length || generate.isPending} onClick={run} className="bg-[#17365d]">{generate.isPending ? "生成中…" : "問題案を生成"}</Button></div></div> : <div className="space-y-4"><div className="rounded-xl border border-emerald-100 bg-emerald-50 p-4"><p className="text-sm font-bold text-emerald-700">{drafts.length}件の問題案を編集できます</p><p className="mt-1 text-xs text-emerald-700/70">保存後も承認するまでは受験者へ公開されません。</p></div>{saveMessage && <div className="rounded-xl border border-sky-100 bg-sky-50 px-4 py-3 text-xs font-semibold text-sky-700">{saveMessage}</div>}{drafts.map((draft, index) => <Card key={index} className="border border-slate-200 shadow-none"><CardContent className="space-y-4 p-5"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><select value={draft.difficulty ?? "standard"} onChange={(e) => updateDraft(index, { difficulty: e.target.value })} className="rounded-lg border border-slate-200 px-2 py-1 text-xs font-semibold text-[#3975a8]"><option value="basic">基礎</option><option value="standard">標準</option><option value="advanced">上級</option></select><select value={draft.type ?? "single"} onChange={(e) => updateDraft(index, { type: e.target.value })} className="rounded-lg border border-slate-200 px-2 py-1 text-xs font-semibold text-[#3975a8]">{Object.entries(labels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><Badge variant="outline">{draft._approved ? "承認済み" : draft._held ? "保留" : "承認待ち"}</Badge></div></div><label className="block text-xs font-bold text-slate-600">設問<textarea value={draft.prompt ?? ""} onChange={(e) => updateDraft(index, { prompt: e.target.value })} className="mt-2 min-h-[80px] w-full rounded-lg border border-slate-200 p-3 text-sm font-normal" /></label><label className="block text-xs font-bold text-slate-600">選択肢（1行1選択肢）<textarea value={(draft.options ?? []).join("\n")} onChange={(e) => updateDraft(index, { options: e.target.value.split("\n").filter(Boolean) })} className="mt-2 min-h-[70px] w-full rounded-lg border border-slate-200 p-3 text-sm font-normal" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-slate-600">正答<Input value={String(draft.answer ?? "")} onChange={(e) => updateDraft(index, { answer: e.target.value })} className="mt-2" /></label><label className="text-xs font-bold text-slate-600">配点<Input type="number" value={Number(draft.points ?? 10)} onChange={(e) => updateDraft(index, { points: Number(e.target.value) })} className="mt-2" /></label></div><label className="block text-xs font-bold text-slate-600">解説<textarea value={draft.explanation ?? ""} onChange={(e) => updateDraft(index, { explanation: e.target.value })} className="mt-2 min-h-[80px] w-full rounded-lg border border-slate-200 p-3 text-sm font-normal" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-slate-600">タグ（カンマ区切り）<Input value={(draft.tags ?? []).join(", ")} onChange={(e) => updateDraft(index, { tags: e.target.value.split(",").map((tag: string) => tag.trim()).filter(Boolean) })} className="mt-2" /></label><div className="space-y-2 rounded-lg bg-slate-50 p-3"><p className="text-xs font-bold text-slate-600">根拠</p>{(draft.evidence ?? []).map((e: any, evidenceIndex: number) => <div key={evidenceIndex} className="grid gap-2 sm:grid-cols-3"><Input value={e.material ?? ""} onChange={(event) => updateDraft(index, { evidence: draft.evidence.map((item: any, itemIndex: number) => itemIndex === evidenceIndex ? { ...item, material: event.target.value } : item) })} placeholder="資料名" className="text-xs" /><Input type="number" value={e.page ?? 1} onChange={(event) => updateDraft(index, { evidence: draft.evidence.map((item: any, itemIndex: number) => itemIndex === evidenceIndex ? { ...item, page: Number(event.target.value) } : item) })} placeholder="ページ" className="text-xs" /><Input value={e.heading ?? ""} onChange={(event) => updateDraft(index, { evidence: draft.evidence.map((item: any, itemIndex: number) => itemIndex === evidenceIndex ? { ...item, heading: event.target.value } : item) })} placeholder="見出し" className="text-xs" /></div>)}</div></div><div className="flex justify-end gap-2"><Button variant="outline" disabled={draft._approved || edit.isPending || review.isPending} onClick={() => hold(index)}>{draft._held ? "保留中" : "保留にする"}</Button><Button variant="outline" disabled={draft._approved || edit.isPending || review.isPending} onClick={() => reject(index)} className="border-rose-200 text-rose-600">{draft._rejected ? "差し戻し済み" : "差し戻す"}</Button><Button disabled={draft._approved || edit.isPending || review.isPending} onClick={() => approveOne(index)} className="bg-[#17365d]">{draft._approved ? "承認済み" : "保存してこの問題を承認"}</Button></div></CardContent></Card>)}<div className="flex justify-end gap-3"><Button variant="outline" onClick={onClose}>後で確認</Button><Button disabled={edit.isPending || !drafts.length} onClick={saveAll} className="bg-[#3975a8]">編集内容をすべて保存</Button></div></div>}</CardContent></Card></div>;
}

function GeneratorModal({ generated, setGenerated, onClose, onDone }: { generated: boolean; setGenerated: (v: boolean) => void; onClose: () => void; onDone: () => void }) { return <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#0d2139]/45 p-4 backdrop-blur-sm"><Card className="max-h-[92vh] w-full max-w-3xl overflow-y-auto border-0 shadow-2xl"><CardHeader className="flex-row items-start justify-between"><div><div className="flex items-center gap-2"><Sparkles className="h-5 w-5 text-[#c2773b]" /><CardTitle className="text-xl text-[#1b3453]">資料ベース問題生成</CardTitle></div><p className="mt-1 text-sm text-slate-400">外部知識ではなく、選択した資料の根拠だけで問題案を作成します。</p></div><button onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"><X className="h-5 w-5" /></button></CardHeader><CardContent className="space-y-5">{!generated ? <><div><p className="mb-2 text-xs font-bold text-slate-600">使用する資料</p><div className="space-y-2">{materials.slice(0, 2).map((m, i) => <label key={m.title} className="flex items-center gap-3 rounded-xl border border-slate-200 p-3"><input type="checkbox" defaultChecked={i === 0} className="h-4 w-4 accent-[#17365d]" /><FileText className="h-4 w-4 text-[#3975a8]" /><span className="flex-1 text-sm font-semibold text-slate-700">{m.title}</span><span className="text-xs text-slate-400">{m.pages}ページ</span></label>)}</div></div><div className="grid gap-4 sm:grid-cols-3"><label className="text-xs font-bold text-slate-600">問題数<Input type="number" defaultValue="5" className="mt-2" /></label><label className="text-xs font-bold text-slate-600">難易度<select className="mt-2 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal"><option>標準中心</option><option>基礎中心</option><option>上級中心</option></select></label><label className="text-xs font-bold text-slate-600">配点<Input type="number" defaultValue="10" className="mt-2" /></label></div><div><p className="mb-2 text-xs font-bold text-slate-600">問題形式（複数選択）</p><div className="flex flex-wrap gap-2">{questionTypes.map((type, i) => <button key={type} className={`rounded-lg border px-3 py-2 text-xs font-semibold ${i === 0 || i === 5 || i === 6 ? "border-[#9fc1da] bg-[#eef6fc] text-[#2c638f]" : "border-slate-200 text-slate-500"}`}>{type}</button>)}</div></div><div className="rounded-xl bg-[#fff8ef] p-4"><div className="flex items-center gap-2 text-xs font-bold text-[#a96532]"><Target className="h-4 w-4" />品質条件</div><p className="mt-2 text-xs leading-5 text-slate-500">複数ページ/複数資料の参照、資料固有の条件・数値・例外を含む問題を70%以上生成します。</p></div><div className="flex justify-end gap-3"><Button variant="outline" onClick={onClose}>キャンセル</Button><Button onClick={() => setGenerated(true)} className="bg-[#17365d] hover:bg-[#214c7c]"><Sparkles className="mr-2 h-4 w-4" />問題案を生成</Button></div></> : <><div className="rounded-xl border border-emerald-100 bg-emerald-50 p-4"><div className="flex items-center gap-2 text-sm font-bold text-emerald-700"><Check className="h-4 w-4" />5件の問題案を下書き生成しました</div><p className="mt-1 text-xs text-emerald-700/70">公開されていません。根拠を確認してから承認してください。</p></div><div className="rounded-2xl border border-slate-200 p-5"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><Badge className="bg-[#eef4fa] text-[10px] text-[#3975a8] hover:bg-[#eef4fa]">資料比較</Badge><Badge variant="outline" className="text-[10px] text-slate-500">上級 · 15点</Badge></div><span className="text-xs font-bold text-[#c2773b]">承認待ち</span></div><h3 className="mt-4 text-base font-bold leading-6 text-[#203956]">ケースAとケースBの記録を比較したとき、初動対応の優先順位が異なる理由として最も適切なものを選びなさい。</h3><div className="mt-4 space-y-2">{["顧客影響の範囲と重大度の判定条件が異なるため", "担当者の経験年数が異なるため", "対応に必要な時間が異なるため", "記録された日時が異なるため"].map((o, i) => <div key={o} className={`rounded-lg border px-3 py-2.5 text-sm ${i === 0 ? "border-[#9fc1da] bg-[#f2f8fd] font-semibold text-[#2c638f]" : "border-slate-100 text-slate-500"}`}><span className="mr-2 text-xs font-bold">{String.fromCharCode(65 + i)}.</span>{o}</div>)}</div><div className="mt-4 rounded-xl bg-slate-50 p-4"><p className="text-[11px] font-bold uppercase tracking-wider text-slate-400">根拠と解説</p><p className="mt-2 text-xs leading-5 text-slate-600">「インシデント対応規程」p.7「重大度判定」と「Q2 ケーススタディ集」p.12「ケース別初動」の記載を比較。顧客影響が広範囲の場合は報告を先行する条件が根拠です。</p></div></div><Textarea defaultValue="確認コメント（任意）" className="min-h-[70px] text-sm text-slate-500" /><div className="flex justify-end gap-3"><Button variant="outline" onClick={onClose}>後で確認</Button><Button onClick={onDone} className="bg-[#17365d] hover:bg-[#214c7c]"><FileCheck2 className="mr-2 h-4 w-4" />下書きとして登録</Button></div></>}</CardContent></Card></div>; }
